Is the documentation of go regarding the &#x27;map&#x27; data type
and the usage of the function &#x27;make&#x27; out of date?<p>Because I can&#x27;t see any difference in:<p><pre><code>    package main

    import (
        &quot;fmt&quot;
    )

    func main() {
       m1 := map[string]int{}
       m1[&quot;a&quot;] = 1
       fmt.Printf(&quot;%d
&quot;, m1[&quot;a&quot;])

       m2 := make(map[string]int)
       m2[&quot;b&quot;] = 2
       fmt.Printf(&quot;%d
&quot;, m2[&quot;b&quot;])
    }</code></pre>
